// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address caller, address newKeeper) public {
        vm.assume(caller != address(0));

        vm.prank(caller);
        bool ok;
        try c.setKeeper(newKeeper) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.keeper() == newKeeper);
        } else {
            assertTrue(c.keeper() == address(0));
        }
    }
}
